// ─── ESTRAI AWB E CLASSIFICA ALLEGATI ───
//
// Input: allegati dalla mail FedEx (da 'Get many attachments')
// Output: un singolo item con awb, dateFormatted, yearMonth,
//         emailId, emailFrom, emailSubject, ciAttachment, plAttachment
//
// Il contenuto degli allegati arriva dal nodo Outlook come
// campo 'contentBytes' (base64). I fallback coprono altri nomi
// che n8n potrebbe usare a seconda della versione del node.

const items = $input.all();

// ── Metadati email ──
const emailItem    = $('📧 Trigger - Nuova Mail FedEx').item.json;
const emailId      = emailItem.id      || '';
const emailFrom    = emailItem.from    || '';
const emailSubject = emailItem.subject || '';

// ── Formattazione data (stile italiano) ──
const now   = new Date();
const day   = String(now.getDate()).padStart(2, '0');
const month = String(now.getMonth() + 1).padStart(2, '0');
const year  = now.getFullYear();
const dateFormatted = `${day}/${month}/${year}`;
const yearMonth     = `${year}-${month}`;

// ── Classificazione allegati ──
let ciAttachment = null;
let plAttachment = null;
let awb = '';

for (const item of items) {
  const rawName = item.json?.name || '';
  const name    = rawName.toUpperCase();

  // Contenuto base64: Outlook lo chiama 'contentBytes'; fallback su altri nomi
  const content = item.json?.contentBytes
               || item.json?.content
               || item.json?.data
               || '';

  // Prova a ricavare AWB: prima un numero di 12 cifre nel nome file,
  // poi il pattern legacy  CI<cifre>_<cifre>  (es. CI123456789012_001)
  if (!awb) {
    const m12 = rawName.match(/(\d{12})/);
    if (m12) awb = m12[1];
  }
  if (!awb) {
    const mCI = rawName.match(/CI(\d+_\d+)/i);
    if (mCI) awb = mCI[0]; // include prefisso CI se non ci sono 12 cifre pure
  }

  // Classifica in base al nome file
  if (
    name.startsWith('CI') ||
    name.includes('_CI.') ||
    name.includes('COMMERCIAL_INVOICE') ||
    name.includes('COMMERCIAL INVOICE')
  ) {
    ciAttachment = { name: rawName, content };
  } else if (
    name.startsWith('PL') ||
    name.includes('_PL.') ||
    name.includes('PACKING_LIST') ||
    name.includes('PACKING LIST')
  ) {
    plAttachment = { name: rawName, content };
  }
}

return [{
  json: {
    awb,
    dateFormatted,
    yearMonth,
    emailId,
    emailFrom,
    emailSubject,
    ciAttachment,
    plAttachment
  }
}];

// Recupera l'ID della cartella AWB appena creata
// Se la cartella esisteva già, continueOnFail la passa comunque
const folderData = $input.first().json;
const awbFolderId = folderData.id || folderData.parentReference?.id || '';

const parsed = $('⚙️ Estrai AWB e Classifica Allegati').first().json;

return [{
  json: {
    ...parsed,
    awbFolderId
  }
}];

const ciAtt = $('⚙️ Estrai AWB e Classifica Allegati').first().json.ciAttachment;
const ciBase64 = ciAtt?.content || ciAtt?.data || '';

if (!ciBase64) {
  throw new Error('Contenuto CI non trovato negli allegati');
}

return [{
  json: {
    ...$('⚙️ Recupera ID Cartella AWB').first().json,
    ciBase64
  }
}];

