const claudeResponse = $input.first().json;
const rawText = claudeResponse.content?.[0]?.text || '';

let extracted;
try {
  const cleaned = rawText.replace(/```json|```/g, '').trim();
  extracted = JSON.parse(cleaned);
} catch(e) {
  throw new Error('Claude non ha restituito JSON valido: ' + rawText.substring(0, 300));
}

const prev = $('⚙️ Recupera ID Cartella AWB').first().json;

// GATE DI QUALITÀ
const errors = [];
if (!prev.awb || prev.awb.length !== 12) errors.push('AWB non valido o non lungo 12 cifre: ' + prev.awb);
if (!extracted.InvoiceNumber) errors.push('Numero fattura mancante');
if (!extracted.TotalAmount || parseFloat(extracted.TotalAmount) <= 0) errors.push('Importo totale non valido o zero');
if (!extracted.HSCode) errors.push('HS Code mancante');
if (!extracted.OriginCountry) errors.push('Paese di origine mancante');

return [{
  json: {
    awb: prev.awb,
    awbFolderId: prev.awbFolderId,
    dateFormatted: prev.dateFormatted,
    yearMonth: prev.yearMonth,
    emailId: prev.emailId,
    emailFrom: prev.emailFrom,
    emailSubject: prev.emailSubject,
    ciAttachment: prev.ciAttachment,
    plAttachment: prev.plAttachment,
    // Dati estratti
    InvoiceNumber: extracted.InvoiceNumber || '',
    InvoiceDate: extracted.InvoiceDate || '',
    SupplierName: extracted.SupplierName || '',
    HSCode: extracted.HSCode || '',
    OriginCountry: extracted.OriginCountry || '',
    TradeTerms: extracted.TradeTerms || '',
    Currency: extracted.Currency || 'USD',
    TotalAmount: extracted.TotalAmount || '0',
    TotalAmountFormatted: extracted.TotalAmountFormatted || '0',
    Description: extracted.Description || '',
    SignatoryName: extracted.SignatoryName || 'Vincenzo Reda',
    // Dati fissi importatore — MODIFICA QUI se cambiano
    ImporterCompanyName: 'Universal Science S.r.l.',
    ImporterVAT: '05595260968',
    ImporterAddress: 'Via Adige 30 – 20006 – Pregnana Milanese (MI)',
    // Validazione
    hasErrors: errors.length > 0,
    errors: errors
  }
}];

